    public void foo(String s) {
        // Example 1 from diff: used in constructor expecting int
        java.awt.Color c1 = new java.awt.Color(0, java.lang.Integer.valueOf(s), 0);
        // Example 2 from diff: explicit unboxing
        int val = java.lang.Integer.valueOf(s).intValue();
        // Example 3 from diff: used in method expecting int
        // (Assuming setWidth takes int, similar to org.eclipse.swt.widgets.TableColumn.setWidth)
        Object col = null;
        if (col instanceof org.eclipse.swt.widgets.TableColumn) {
            ((org.eclipse.swt.widgets.TableColumn) col).setWidth(java.lang.Integer.valueOf(s));
        }
    }
    // This case would also be transformed by the JDT cleanup, as autoboxing handles the Integer object requirement efficiently.
    public java.lang.Integer getIntegerObject(String s) {
        return java.lang.Integer.valueOf(s);
    }
}

