negativeExample:
public class MyClass {
    public void otherMethods() {
        // Different Wrapper class, should not match Integer.valueOf(String)
        java.lang.Long.valueOf("123L");

        // Primitive argument, not String, should not match Integer.valueOf(String)
        java.lang.Integer.valueOf(123);

        // Different method name, should not match
        String.valueOf(42);

        // Two-argument Integer.valueOf (not covered by this specific rule, but by a similar one)
        int base = java.lang.Integer.valueOf("100", 16);
    }
}
